-- evt:password
RegisterEvent(42, "Door", function(continueStep)
    if continueStep == 2 then
        evt.SetDoorState(11, DoorAction.Open)
        XeenQuests.hook("q-c8.l2_door")
        return
    end
    if continueStep ~= nil then
        XeenQuests.hook("q-c8.l2_wrong")
        return
    end
    if not (not (IsQBitSet(QBit(112161)))) then
        XeenQuests.hook("q-c8.l2_door")
        return
    end
    evt.SetMessage("STOP!  What is the password?")
    evt.AskQuestion(42, 1, 0, 2, "Password:", {"There wolf", "therewolf", "There-wolf"})
end, "Door")

